/bin/zsh -lc "python3 build_answer.py && python3 - <<'PY'
import json,re,collections,xml.etree.ElementTree as ET
from html import unescape
from pathlib import Path
s=json.load(open('source.json')); a=json.load(open('answer.json')); ref=json.load(open('reference-targets.json'))
assert len(a)==len(s)==24
kinds={'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
def txt(x): return unescape(re.sub('<["'^>]+>'"','',x or ''))
for source,row in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']: assert row[k]==source[k], (row['number'],k)
 imp=row['substantive_impact']; assert imp['version']==1
 for f in ['assessment','scope_limitations','new_burdens_review']: assert len(imp[f])>=40
 assert row['status'] in {'retained_unchanged','rewrite_draft'}
 if row['status']=='retained_unchanged':
  assert row['proposed_xml'] is None and row['classification']=='retained_necessary' and imp['classification']=='retained_necessary' and not imp['effects']
 else:
  rt=ET.fromstring('<root>'+row['proposed_xml']+'</root>')
  for n in rt.iter():
   if n.tag=='root': continue
   assert n.tag in allowed,n.tag
   assert all(k in {'colspan','rowspan'} and v.isdigit() for k,v in n.attrib.items())
  assert txt(row['proposed_xml']).strip()
 if row.get('change_type')=='normative_reduction':
  assert row['reform_policy_id']=='editorial_direction_2026_10_19'
  assert all(len(x)>=30 for x in row['removed_provisions'])
 if row.get('change_type')=='full_repeal':
  assert row['repeal_policy_id']=='editorial_direction_2026_10_19' and len(row['repeal_scope'])>=30
  assert txt(row['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé'))
 if source.get('benefit_check_required'): assert len(row.get('benefit_review',''))>=100
 for e in imp['effects']:
  assert e['kind'] in kinds
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for f in ['kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote']: assert isinstance(e[f],str) and e[f]
  assert len(e['source_quote'])>=12 and e['source_quote'] in txt(source['source_xml']),(row['number'],'source quote',e['source_quote'])
  assert len(e['proposed_quote'])>=12 and e['proposed_quote'] in txt(row['proposed_xml']),(row['number'],'proposed quote')
 key=source['code_id']+'|'+source['source_id']; req=ref['requirements'][key]
 assert [x['target_key'] for x in row['reference_checks']]==req
 for c in row['reference_checks']:
  assert c['view_sha256']==ref['targets'][c['target_key']]['view_sha256'] and len(c['assessment'])>=80
print('VALIDATION OK',len(a),'articles',Path('answer.json').stat().st_size,'bytes')
print('STATUS',dict(collections.Counter(x['status'] for x in a)))
print('IMPACTS',dict(collections.Counter(x['substantive_impact']['classification'] for x in a)))
print('CHECKS',sum(len(x['reference_checks']) for x in a))
for x in a: print(x['number'],x['status'],x.get('change_type',''),len(x['proposed_xml'] or ''))
PY"

